// src/runtime/prefill/epochal_consolidator.cc: merge intents into epoch
void EpochalConsolidator::Submit(Intent i) {
  auto key = affinityKey(i);
  auto &epoch = openEpochs_[key];
  epoch.push_back(std::move(i));
  if (epoch.windowElapsed()) emitConsolidatedPrefill(key);
}

// src/runtime/scheduler/entropy_scheduler.cc: compute score
double EntropyScheduler::score(const DecodeTask &t) {
  double ent = computePrefixEntropy(t.epoch());
  return baseScore(t) - ent * entropyWeight_ + kvWarmthBonus(t.epoch());
}

